// Une el lead con la calificacion del modelo.
const lead = $('Con forma de contactar').first().json;
const salida = [];
for (const item of $input.all()) {
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let cal;
  try {
    cal = JSON.parse(bruto);
  } catch (error) {
    cal = { segmento: 'revisar', interes: 'bajo', que_pide: '', siguiente_paso: 'revisar a mano', motivo: 'calificacion no parseable', borrador: '' };
  }
  salida.push({
    json: {
      ...lead,
      segmento: cal.segmento ?? 'revisar',
      interes: cal.interes ?? 'bajo',
      que_pide: cal.que_pide ?? '',
      siguiente_paso: cal.siguiente_paso ?? '',
      calificacion: cal.motivo ?? '',
      borrador_respuesta: cal.borrador ?? '',
      proxima_accion: 'primera respuesta hoy',
    },
  });
}
return salida;

