// Agrega las cifras de la semana para el informe.
const ahora = new Date();
const hace7 = new Date(ahora.getTime() - 7 * 24 * 3600 * 1000);
const hace14 = new Date(ahora.getTime() - 14 * 24 * 3600 * 1000);
const filas = $input.all().map((i) => i.json);

function resumen(desde, hasta) {
  const nuevos = filas.filter((f) => {
    const fecha = new Date(f.fecha_entrada);
    return fecha >= desde && fecha < hasta;
  });
  const porCanal = {};
  for (const f of nuevos) {
    porCanal[f.canal] = (porCanal[f.canal] || 0) + 1;
  }
  const ganados = filas.filter((f) => f.estado === 'ganado');
  const perdidos = filas.filter((f) => f.estado === 'perdido');
  const motivos = {};
  for (const f of perdidos) {
    const motivo = f.motivo_perdida || 'sin motivo anotado';
    motivos[motivo] = (motivos[motivo] || 0) + 1;
  }
  const vivos = filas.filter((f) => !['ganado', 'perdido', 'descartado'].includes(f.estado));
  const sinAccion = vivos.filter((f) => !f.proxima_accion);
  const propuestas = vivos.filter((f) => f.estado === 'propuesta_enviada');
  return {
    nuevos: nuevos.length,
    por_canal: porCanal,
    ganados_totales: ganados.length,
    perdidos_totales: perdidos.length,
    motivos_perdida: motivos,
    vivos: vivos.length,
    sin_proxima_accion: sinAccion.length,
    propuestas_abiertas: propuestas.length,
  };
}

return [{
  json: {
    resumen_semana: JSON.stringify(resumen(hace7, ahora)),
    resumen_anterior: JSON.stringify(resumen(hace14, hace7)),
    semana: ahora.toISOString().slice(0, 10),
  },
}];

